properties.unscaledStyleSheet:
QPushButton#updateNoticeButton {
    background-color: @accent-tint;
    color: @accent-soft;
    border: 1px solid @accent-tint-border;
    border-radius: 11px;
    padding: 2px 10px 2px 8px;
    margin: 0 8px;
    font-size: 12px;
    font-weight: 600;
}
QPushButton#updateNoticeButton:hover {
    background-color: @accent-tint-strong;
    border-color: @accent-tint-border-strong;
}
QPushButton#updateNoticeButton:pressed {
    background-color: @accent-muted;
}

properties.scaledStyleSheet:
QPushButton#updateNoticeButton {
    background-color: #e8f1fd;
    color: #0066cc;
    border: 1px solid #9cc4f2;
    border-radius: 11px;
    padding: 2px 10px 2px 8px;
    margin: 0 8px;
    font-size: 12px;
    font-weight: 600;
}
QPushButton#updateNoticeButton:hover {
    background-color: #d6e7fb;
    border-color: #6ea8e8;
}
QPushButton#updateNoticeButton:pressed {
    background-color: #a9c9ee;
}

